class C:
    def __init__(self):
        self.n = 0
    def __iter__(self):
        return self
    def __next__(self):
        if self.n >= 2:
            raise StopIteration
        self.n += 1
        return self.n
c = C()
print(list(c), list(c))

import functools
@functools.lru_cache(maxsize=2)
def sq(x):
    return x * x
sq(1); sq(2); sq(1); sq(3); sq(2)
print(sq.cache_info().hits)

import functools
@functools.cache
def total(xs):
    return sum(xs)
print(total([1, 2, 3]))

import functools
@functools.singledispatch
def kind(x):
    return "other"
@kind.register
def _(x: int):
    return "int"
print(kind(True), kind(2.5))

import functools
class C:
    @functools.cached_property
    def v(self):
        print("computing")
        return 1
a, b = C(), C()
a.v; a.v; b.v
